import functools
import time

def log_execution(func):
    """一个简单的日志装饰器，记录函数调用信息"""
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        print(f"[LOG] 调用函数 {func.__name__}，参数 args={args}, kwargs={kwargs}")
        result = func(*args, **kwargs)
        print(f"[LOG] {func.__name__} 返回 {result}")
        return result
    return wrapper

def timed(repeat=1):
    """带参数的计时装饰器，可指定重复执行次数以消除随机误差"""
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            total_time = 0.0
            for _ in range(repeat):
                start = time.perf_counter()
                result = func(*args, **kwargs)
                end = time.perf_counter()
                total_time += (end - start)
            avg_time = total_time / repeat
            print(f"[TIMER] {func.__name__} 平均执行时间: {avg_time*1000:.3f}ms (重复 {repeat} 次)")
            return result
        return wrapper
    return decorator

# 单个装饰器用法
@log_execution
def add(a, b):
    """返回两个数的和"""
    return a + b

# 带参数的装饰器用法
@timed(repeat=5)
def multiply(x, y):
    return x * y

if __name__ == "__main__":
    add(3, 5)
    multiply(4, 7)

